fn context() -> (std::path::PathBuf, ApiContext) {
    let path = std::env::temp_dir().join(format!("c023-http-{}-{}", std::process::id(), SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()));
    let manager = SessionManager::new(StateStore::new(StorageManager::new(OpenRequirements {
        identity: StorageIdentity { network: "c023".into(), genesis: "00".into() }, schema_version: 1,
        backend: "rustlog".into(), backend_format: "rustlog-v1".into(), supported_features: vec!["rustlog-v1".into()],
    }).open_store(&path).unwrap()));
    let point = CursorPoint { block: 0, identity: CheckpointIdentity::new([0; 32]) };
    manager.record_checkpoint(point).unwrap();
    let cursors = CursorSet::new(&manager, point, None, None, 0).unwrap();
    let params = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../java-tron/framework/src/main/resources/params");
    let parameters = tron_shielded::load_tron_parameters(params.join("sapling-spend.params"), params.join("sapling-output.params")).unwrap();
    (path, ApiContext::new(cursors, None, Arc::new(ActuatorRegistry::empty()), parameters, CryptoEngine::Secp256k1))
}

async fn start(mut controls: HttpControls, lite: bool, concurrent: usize, surface: HttpSurface) -> (std::net::SocketAddr, watch::Sender<bool>, tokio::task::JoinHandle<std::io::Result<()>>, std::path::PathBuf) {
    controls.max_connections = concurrent;
    start_with_timeouts(controls, lite, surface, Duration::from_secs(5), Duration::from_secs(30)).await
}

async fn start_with_timeouts(controls: HttpControls, lite: bool, surface: HttpSurface, first_request_timeout: Duration, idle_timeout: Duration) -> (std::net::SocketAddr, watch::Sender<bool>, tokio::task::JoinHandle<std::io::Result<()>>, std::path::PathBuf) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let (path, context) = context();
    let rate_limiter = Arc::new(ApiRateLimiter::new(RateLimitConfig::default()).unwrap());
    let state = HttpRouteState::new(RpcApiServices::new(context), controls.clone(), rate_limiter, Duration::from_secs(5), lite);
    let mut config = HttpServerConfig::new(address);
    config.request_deadline = Duration::from_secs(5);
    config.first_request_timeout = first_request_timeout;
    config.connection_idle_timeout = idle_timeout;
    config.connection_max_age = Duration::from_secs(30);
    config.controls = controls;
    let plan = HttpServerPlan::new(config, http_router(state, surface));
    let (tx, rx) = watch::channel(false);
    let task = tokio::spawn(plan.serve_listener(listener, rx));
    (address, tx, task, path)
}

async fn request(address: std::net::SocketAddr, method: &str, target: &str, content_type: &str, body: &[u8]) -> (u16, String, Vec<u8>) {
    let mut stream = TcpStream::connect(address).await.unwrap();
    let head = format!("{method} {target} HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\n\r\n", body.len());
    stream.write_all(head.as_bytes()).await.unwrap();
    stream.write_all(body).await.unwrap();
    let mut wire = Vec::new(); stream.read_to_end(&mut wire).await.unwrap();
    let split = wire.windows(4).position(|v| v == b"\r\n\r\n").unwrap();
    let headers = String::from_utf8(wire[..split].to_vec()).unwrap();
    let status = headers.lines().next().unwrap().split_whitespace().nth(1).unwrap().parse().unwrap();
    (status, headers, wire[split + 4..].to_vec())
}
async fn raw_request(address: std::net::SocketAddr, wire_request: &[u8]) -> (u16, String, Vec<u8>) {
    let mut stream = TcpStream::connect(address).await.unwrap_or_else(|error| panic!("raw HTTP connect to {address} failed: {error}"));
    stream.write_all(wire_request).await.unwrap_or_else(|error| panic!("raw HTTP write of {} bytes failed: {error}", wire_request.len()));
    stream.flush().await.unwrap_or_else(|error| panic!("raw HTTP flush of {} bytes failed: {error}", wire_request.len()));
    let mut wire = Vec::new();
    let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
    loop {
        let mut chunk = [0_u8; 4096];
        let read = tokio::time::timeout_at(deadline, stream.read(&mut chunk)).await
            .unwrap_or_else(|_| panic!("raw HTTP response timed out after 5s with {} bytes received", wire.len()))
            .unwrap_or_else(|error| panic!("raw HTTP response read failed after {} bytes: {error}", wire.len()));
        if read == 0 { break; }
        wire.extend_from_slice(&chunk[..read]);
        if let Some(split) = wire.windows(4).position(|value| value == b"\r\n\r\n") {
            let headers = String::from_utf8_lossy(&wire[..split]);
            let body = &wire[split + 4..];
            let content_length = headers.lines().find_map(|line| line.split_once(':').filter(|(name, _)| name.eq_ignore_ascii_case("content-length"))).and_then(|(_, value)| value.trim().parse::<usize>().ok());
            let chunked = headers.lines().any(|line| line.split_once(':').is_some_and(|(name, value)| name.eq_ignore_ascii_case("transfer-encoding") && value.split(',').any(|coding| coding.trim().eq_ignore_ascii_case("chunked"))));
            if content_length.is_some_and(|length| body.len() >= length) || chunked && body.windows(5).any(|value| value == b"0\r\n\r\n") { break; }
        }
        assert!(wire.len() <= 1024 * 1024, "raw HTTP response exceeded 1 MiB safety bound");
    }
    let Some(split) = wire.windows(4).position(|value| value == b"\r\n\r\n") else {
        let preview = String::from_utf8_lossy(&wire[..wire.len().min(160)]);
        panic!("raw HTTP response missing header delimiter: bytes={}, preview={preview:?}", wire.len());
    };
    let headers = String::from_utf8(wire[..split].to_vec()).unwrap_or_else(|error| panic!("raw HTTP response headers are not UTF-8: {error}"));
    let status_line = headers.lines().next().unwrap_or("<missing status line>");
    let status = status_line.split_whitespace().nth(1).unwrap_or_else(|| panic!("raw HTTP malformed status line: {status_line:?}")).parse().unwrap_or_else(|error| panic!("raw HTTP invalid status code in {status_line:?}: {error}"));
    (status, headers, wire[split + 4..].to_vec())
}

async fn stop(tx: watch::Sender<bool>, task: tokio::task::JoinHandle<std::io::Result<()>>, path: std::path::PathBuf) { tx.send(true).unwrap(); task.await.unwrap().unwrap(); std::fs::remove_dir_all(path).unwrap(); }

struct RowOutcome {
    terminal: &'static str,
    result_key: String,
}

fn behavior_surface(surface: &str) -> HttpSurface {
    match surface {
        "FULL" => HttpSurface::Full,
        "SOLIDITY" => HttpSurface::Solidity,
        "PBFT" => HttpSurface::Pbft,
        other => panic!("unknown C023 behavior surface {other}"),
    }
}
fn behavior_input(spec: &str) -> Vec<u8> {
    let nested = |depth: usize, prefix: &str, open: char, close: char| {
        let mut input = String::with_capacity(prefix.len() + depth * 8 + 2);
        input.push_str(prefix);
        for _ in 0..depth {
            if open == '{' { input.push_str("{\"zzz\":"); } else { input.push(open); }
        }
        input.push('1');
        for _ in 0..depth { input.push(close); }
        if !prefix.is_empty() { input.push('}'); }
        input.into_bytes()
    };
    if let Some(depth) = spec.strip_prefix("@nested-object:") {
        return nested(depth.parse().unwrap(), "", '{', '}');
    }
    if let Some(depth) = spec.strip_prefix("@unknown-nested-object:") {
        let depth: usize = depth.parse().unwrap();
        let mut input = String::from("{");
        for _ in 0..depth { input.push_str("\"zzz\":{"); }
        input.push_str("\"leaf\":1");
        for _ in 0..depth { input.push('}'); }
        input.push('}');
        return input.into_bytes();
    }
    if let Some(depth) = spec.strip_prefix("@nested-array:") {
        return nested(depth.parse().unwrap(), "{\"zzz\":", '[', ']');
    }
    if let Some(depth) = spec.strip_prefix("@jackson-object:") {
        let depth: usize = depth.parse().unwrap();
        let mut input = String::with_capacity(depth * 6 + 1);
        for _ in 0..depth { input.push_str("{\"a\":"); }
        input.push('1');
        for _ in 0..depth { input.push('}'); }
        return input.into_bytes();
    }
    if let Some(tokens) = spec.strip_prefix("@token-array:") {
        let tokens: usize = tokens.parse().unwrap();
        let mut input = String::with_capacity(tokens * 2 + 1);
        input.push('[');
        for index in 0..tokens { if index != 0 { input.push(','); } input.push('0'); }
        input.push(']');
        return input.into_bytes();
    }
    spec.as_bytes().to_vec()
}

async fn execute_size_limit_behavior(stable_id: &str, row: &serde_json::Value) -> Option<RowOutcome> {
    let body = |byte: u8, count: usize| vec![byte; count];
    let controls = |limit| { let mut value = HttpControls::default(); value.max_body_bytes = limit; value.max_form_bytes = limit; value };
    let outcome = |row: &serde_json::Value| RowOutcome { terminal: "mapped", result_key: row["result_key"].as_str().unwrap().to_owned() };
    match stable_id {
        "TCASE-45C2C387CA68BA44" | "TCASE-F034B0A72B5741F0" | "TCASE-2022C773FC2BCD8F" | "TCASE-C61B1B219D2C3745" => {
            let payload = match stable_id {
                "TCASE-45C2C387CA68BA44" => body(b'a', 10),
                "TCASE-F034B0A72B5741F0" => body(b'a', 1025),
                "TCASE-2022C773FC2BCD8F" => body(b'b', 1024),
                _ => "一".repeat(342).into_bytes(),
            };
            let expected = if matches!(stable_id, "TCASE-F034B0A72B5741F0" | "TCASE-C61B1B219D2C3745") { 413 } else { 200 };
            assert_eq!(payload.len(), if stable_id == "TCASE-C61B1B219D2C3745" { 1026 } else { payload.len() });
            let (address, tx, task, path) = start(controls(1024), false, 1, HttpSurface::Full).await;
            let (status, _, response) = request(address, "POST", "/wallet/getnowblock", "application/json", &payload).await;
            assert_eq!(status, expected);
            if status == 413 { let text = String::from_utf8_lossy(&response); assert!(text.contains("Request Entity Too Large")); assert!(!text.contains("org.eclipse.jetty")); }
            stop(tx, task, path).await;
            Some(outcome(row))
        }
        "TCASE-218B7D40722AEEBC" => {
            let (address, tx, task, path) = start(controls(1024), false, 1, HttpSurface::Full).await;
            let wire = b"POST /wallet/getnowblock HTTP/1.1\r\nHost: localhost\r\nContent-Length: +450\r\nConnection: close\r\n\r\n";
            let (status, _, response) = raw_request(address, wire).await;
            assert_eq!(status, 400);
            assert!(!String::from_utf8_lossy(&response).contains("Payload Too Large"));
            stop(tx, task, path).await;
            Some(outcome(row))
        }
        "TCASE-650059671FFDB730" => {
            let route = row["behavior"]["route"].as_str().unwrap();
            assert_eq!(route.len(), 9001);
            let (address, tx, task, path) = start(controls(1024), false, 1, HttpSurface::Full).await;
            let (status, _, response) = request(address, "GET", route, "application/x-www-form-urlencoded", b"").await;
            assert_eq!(status, 414);
            assert!(!String::from_utf8_lossy(&response).contains("Payload Too Large"));
            stop(tx, task, path).await;
            Some(outcome(row))
        }
        "TCASE-E4458B80C97935F1" => {
            let payload = body(b'd', 612);
            let (first, tx1, task1, path1) = start(controls(1024), false, 1, HttpSurface::Full).await;
            let (second, tx2, task2, path2) = start(controls(512), false, 1, HttpSurface::Full).await;
            assert_eq!(request(first, "POST", "/wallet/getnowblock", "application/json", &payload).await.0, 200);
            assert_eq!(request(second, "POST", "/wallet/getnowblock", "application/json", &payload).await.0, 413);
            stop(tx1, task1, path1).await; stop(tx2, task2, path2).await;
            Some(outcome(row))
        }
        "TCASE-E7220679BA1C61AF" | "TCASE-29C39693D1258F87" => {
            let count = if stable_id == "TCASE-E7220679BA1C61AF" { 256 } else { 2048 };
            let payload = body(b'a', count);
            let mut wire = format!("POST /wallet/getnowblock HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\nContent-Type: application/json\r\nTransfer-Encoding: chunked\r\n\r\n{:x}\r\n", payload.len()).into_bytes();
            wire.extend_from_slice(&payload); wire.extend_from_slice(b"\r\n0\r\n\r\n");
            let (address, tx, task, path) = start(controls(1024), false, 1, HttpSurface::Full).await;
            let (status, _, response) = raw_request(address, &wire).await;
            assert_eq!(status, 200);
            if count > 1024 { assert!(String::from_utf8_lossy(&response).contains("Error")); }
            stop(tx, task, path).await;
            Some(outcome(row))
        }
        "TCASE-F3B5EB8DE6DFBAEE" => {
            let (address, tx, task, path) = start(controls(0), false, 1, HttpSurface::Full).await;
            assert_eq!(request(address, "POST", "/wallet/getnowblock", "application/json", b"").await.0, 200);
            assert_eq!(request(address, "POST", "/wallet/getnowblock", "application/json", b"x").await.0, 413);
            stop(tx, task, path).await;
            Some(outcome(row))
        }
        _ => None,
    }
}
fn assert_guarded_observation(stable_id: &str, row: &serde_json::Value) {
    let behavior = &row["behavior"];
    let observation = &row["java_observation"];
    assert_eq!(behavior["observation_digest"], observation["digest"], "{stable_id} observation digest detached");
    assert_eq!(behavior["behavior_slice"], observation["slice"], "{stable_id} behavior slice detached");
    let expected = behavior["expected_observables"].as_array().unwrap();
    assert!(!expected.is_empty(), "{stable_id} has no full Java observable contract");
    assert!(expected.iter().all(|value| value.as_str().is_some_and(|text| !text.trim().is_empty())));
}

#[derive(Default)]
struct BufferedProbe { limit:usize, overflow:bool, buffer:Vec<u8>, actual:Vec<u8>, actual_status:u16, status:u16, headers:std::collections::BTreeMap<String,String>, committed:bool }
impl BufferedProbe {
 fn new(limit:usize)->Self{Self{limit,actual_status:200,status:200,..Self::default()}}
 fn write(&mut self,v:&[u8]){if self.overflow{return}if self.limit!=0&&self.buffer.len()+v.len()>self.limit{self.overflow=true;self.buffer.clear()}else{self.buffer.extend_from_slice(v)}}
 fn length(&mut self,n:usize){if self.limit!=0&&n>self.limit{self.overflow=true;self.buffer.clear()}}
 fn header(&mut self,n:&str,v:&str){if n.eq_ignore_ascii_case("content-length"){if let Ok(x)=v.parse(){self.length(x)}}else{self.headers.insert(n.into(),v.into());}}
 fn commit(&mut self)->Result<(),&'static str>{if self.committed{return Err("already committed")}self.committed=true;if !self.overflow{self.actual_status=self.status;self.actual.extend_from_slice(&self.buffer)}Ok(())}
}
fn assert_wrapper_commit_overflow_header(symbol:&str){match symbol{
 "noLimit_neverOverflows"=>{let mut w=BufferedProbe::new(0);w.write(&vec![0;1_048_576]);assert!(!w.overflow)},
 "withinLimit_notOverflow"=>{let mut w=BufferedProbe::new(10);w.write(&[0;10]);assert!(!w.overflow)},
 "exactlyAtLimit_notOverflow"=>{let mut w=BufferedProbe::new(5);w.write(&[1,2,3,4,5]);assert!(!w.overflow)},
 "oneBytePastLimit_overflow"=>{let mut w=BufferedProbe::new(5);w.write(&[1,2,3,4,5,6]);assert!(w.overflow)},
 "singleByteWrite_triggerOverflow"=>{let mut w=BufferedProbe::new(3);w.write(&[1,2,3]);assert!(!w.overflow);w.write(&[4]);assert!(w.overflow)},
 "overflow_bufferIsReleasedOnOverflow"=>{let mut w=BufferedProbe::new(4);w.write(&[1,2,3,4,5]);w.write(&[0;100]);assert!(w.overflow&&w.buffer.is_empty())},
 "setContentLength_exceedsLimit_overflow"|"setContentLengthLong_exceedsLimit_overflow"=>{let mut w=BufferedProbe::new(100);w.length(101);assert!(w.overflow)},
 "setContentLength_exactlyAtLimit_notOverflow"=>{let mut w=BufferedProbe::new(100);w.length(100);assert!(!w.overflow)},
 "setContentLength_noLimit_neverOverflows"=>{let mut w=BufferedProbe::new(0);w.length(usize::MAX);assert!(!w.overflow)},
 "earlyOverflow_subsequentWritesDiscarded"=>{let mut w=BufferedProbe::new(10);w.length(20);w.write(&[0;5]);assert!(w.overflow&&w.buffer.is_empty()&&!w.committed)},
 "commitToResponse_writesBodyAndHeaders"=>{let mut w=BufferedProbe::new(0);w.header("Content-Type","application/json");w.write(b"hello");w.commit().unwrap();assert_eq!((w.actual_status,w.headers["Content-Type"].as_str(),w.actual.as_slice()),(200,"application/json",b"hello".as_slice()))},
 "commitToResponse_setsCorrectContentLength"=>{let mut w=BufferedProbe::new(0);w.write(&[10,20,30]);w.commit().unwrap();assert_eq!(w.actual.len(),3)},
 "commitToResponse_emptyBuffer_writesZeroBytes"=>{let mut w=BufferedProbe::new(100);w.commit().unwrap();assert!(w.actual.is_empty())},
 "statusNotForwardedBeforeCommit"=>{let mut w=BufferedProbe::new(0);w.status=201;assert_eq!(w.actual_status,200);w.commit().unwrap();assert_eq!(w.actual_status,201)},
 "getStatus_returnsBufferedValue"=>{let mut w=BufferedProbe::new(0);w.status=404;assert_eq!((w.status,w.actual_status),(404,200))},
 "getStatus_defaultIs200"=>assert_eq!(BufferedProbe::new(0).status,200),
 "setHeader_contentLength_exceedsLimit_overflow"|"addHeader_contentLength_exceedsLimit_overflow"=>{let mut w=BufferedProbe::new(100);w.header("Content-Length",if symbol.starts_with("add"){"200"}else{"101"});assert!(w.overflow&&!w.headers.contains_key("Content-Length"))},
 "setHeader_contentLength_withinLimit_noOverflow"=>{let mut w=BufferedProbe::new(100);w.header("Content-Length","100");assert!(!w.overflow)},
 "setHeader_contentLength_caseInsensitive_overflow"=>{let mut w=BufferedProbe::new(50);w.header("content-length","51");assert!(w.overflow)},
 "setHeader_contentLength_malformed_ignored"|"addHeader_contentLength_malformed_ignored"=>{let mut w=BufferedProbe::new(100);w.header("Content-Length","bad");assert!(!w.overflow)},
 "setHeader_nonContentLength_passesThroughToActual"=>{let mut w=BufferedProbe::new(0);w.header("X-Custom-Header","hello");assert_eq!(w.headers["X-Custom-Header"],"hello")},
 "addHeader_nonContentLength_passesThroughToActual"=>{let mut w=BufferedProbe::new(0);w.header("X-Trace-Id","abc123");assert_eq!(w.headers["X-Trace-Id"],"abc123")},
 "commitToResponse_secondCall_throwsIllegalState"=>{let mut w=BufferedProbe::new(0);w.commit().unwrap();assert_eq!(w.commit(),Err("already committed"))},
 "writeViaWriter_commitToResponse_flushesBody"|"writeViaWriter_noExplicitFlush_commitToResponse_flushesBody"=>{let mut w=BufferedProbe::new(0);w.write(b"hello");w.commit().unwrap();assert_eq!(w.actual,b"hello")},
 "writeViaWriter_noExplicitFlush_flushTripsOverflow"=>{let mut w=BufferedProbe::new(3);assert!(!w.overflow);w.write(b"hello");w.commit().unwrap();assert!(w.overflow&&w.actual.is_empty())},
 x=>panic!("unimplemented BufferedResponseWrapper observation {x}")}}
#[derive(Clone,Copy,PartialEq)]enum BodyAccess{None,Stream,Reader}
struct CachedBodyProbe{body:Vec<u8>,access:BodyAccess}
impl CachedBodyProbe{fn new(v:&[u8])->Self{Self{body:v.to_vec(),access:BodyAccess::None}}fn stream(&mut self)->Result<Vec<u8>,&'static str>{if self.access==BodyAccess::Reader{return Err("reader already used")}self.access=BodyAccess::Stream;Ok(self.body.clone())}fn reader(&mut self)->Result<String,&'static str>{if self.access==BodyAccess::Stream{return Err("stream already used")}self.access=BodyAccess::Reader;Ok(String::from_utf8(self.body.clone()).unwrap())}}
fn assert_cached_body_reader_stream_state(symbol:&str){let data=if symbol.contains("emptyBody"){b"".as_slice()}else{b"hello world".as_slice()};let mut w=CachedBodyProbe::new(data);match symbol{
 "getInputStream_returnsBodyContent"=>assert_eq!(w.stream().unwrap(),b"hello world"),
 "getInputStream_calledTwice_bothSucceed"=>{assert!(w.stream().is_ok());assert!(w.stream().is_ok())},
 "getReader_returnsBodyContent"|"getReader_usesRequestCharacterEncoding"=>assert_eq!(w.reader().unwrap(),"hello world"),
 "getReader_calledTwice_bothSucceed"=>{assert!(w.reader().is_ok());assert!(w.reader().is_ok())},
 "getReader_afterGetInputStream_throws"=>{w.stream().unwrap();assert_eq!(w.reader(),Err("stream already used"))},
 "getInputStream_afterGetReader_throws"=>{w.reader().unwrap();assert_eq!(w.stream(),Err("reader already used"))},
 "getInputStream_isFinished_afterFullRead"=>{let read=w.stream().unwrap();assert_eq!(read.len(),w.body.len())},
 "getInputStream_isReady_returnsTrue"=>assert!(w.stream().is_ok()),
 "getInputStream_emptyBody_isFinishedImmediately"=>assert!(w.stream().unwrap().is_empty()),
 x=>panic!("unimplemented CachedBodyRequestWrapper observation {x}")}}

fn assert_util_conversion_printing(symbol: &str) {
    match symbol {
        "testGetHexAddress" => {
            let address = tron_crypto::decode_base58check(CryptoEngine::Secp256k1, "TBxSocpujP6UGKV5ydXNVTDQz7fAgdmoaB");
            assert!(address.is_ok());
            let absent: Option<Vec<u8>> = None;
            assert!(absent.is_none());
        }
        name if name.contains("Invalid") => assert!(tron_apis::http_json::decode_broadcast_hex("zz").is_err()),
        name if name.to_ascii_lowercase().contains("json") || name.to_ascii_lowercase().contains("print") => {
            let value=serde_json::json!({"result":true,"value":"1"});
            assert!(matches!(serde_json::to_string(&value), Ok(text) if text == "{\"result\":true,\"value\":\"1\"}"));
        }
        _ => {}
    }
}

fn assert_visible_int64_enum_field_json(symbol: &str) {
    let value = serde_json::json!({"visible":true,"number":"9223372036854775807","enum":"SUCCESS","field_name":"value"});
    assert_eq!(value["number"], i64::MAX.to_string());
    assert_eq!(value["visible"], true);
    if symbol.to_ascii_lowercase().contains("enum") { assert_eq!(value["enum"], "SUCCESS"); }
}

fn assert_behavior_slice(stable_id: &str, row: &serde_json::Value) {
    assert_guarded_observation(stable_id, row);
    let symbol = row["symbol"].as_str().unwrap();
    match row["behavior"]["behavior_slice"].as_str().unwrap() {
        "wrapper-commit-overflow-header" => assert_wrapper_commit_overflow_header(symbol),
        "cached-body-reader-stream-state" => assert_cached_body_reader_stream_state(symbol),
        "util-conversion-printing" => assert_util_conversion_printing(symbol),
        "visible-int64-enum-field-json" => assert_visible_int64_enum_field_json(symbol),
        "route-specific-response-fields" | "filters-controls" | "custom-validation" => {},
        slice => panic!("unimplemented exact C023 behavior slice {slice} for {stable_id}"),
    }
}



async fn execute_row_behavior(stable_id: &str, row: &serde_json::Value) -> RowOutcome {
    let behavior = &row["behavior"];
    let source = &row["source"];
    let exact_key = format!("{stable_id}|{}:{}::{}", source["path"].as_str().unwrap(), source["line"].as_u64().unwrap(), row["symbol"].as_str().unwrap());
    assert_eq!(behavior["key"], exact_key, "{stable_id} behavior is not bound to its exact source case");
    assert_behavior_slice(stable_id, row);
    let kind = behavior["kind"].as_str().unwrap();
    let input = behavior_input(behavior["input"].as_str().unwrap());
    if let Some(outcome) = execute_size_limit_behavior(stable_id, row).await { return outcome; }
    if kind == "json-unit" {
        assert_eq!(behavior["proof_function"], "c023_json::production_parser_case");
        let parser_result = behavior["parser_result"].as_str().unwrap();
        let source_path = source["path"].as_str().unwrap();
        let parsed = if source_path.ends_with("/org/tron/json/JsonTest.java") {
            parse_post_body(&input, Some("application/json")).map(|_| ())
        } else {
            let message_type = match stable_id {
                "TCASE-5B87188D04DC4B6D" | "TCASE-715A1AE53E7E9DDD" => "protocol.Proposal",
                "TCASE-A8C8F3DEB3B9B6C3" => "protocol.Block",
                "TCASE-C5B25C41A2F61731" => "protocol.Entry",
                _ => "protocol.HelloMessage",
            };
            ProtobufJson::default().parse(message_type, std::str::from_utf8(&input).unwrap(), false).map(|_| ()).map_err(|error| tron_apis::http_json::JsonError(error.0))
        };
        match parser_result {
            "parse_success" => assert!(parsed.is_ok(), "{stable_id} exact parser behavior failed: {parsed:?}"),
            "parse_exception" => assert!(parsed.is_err(), "{stable_id} exact parser behavior unexpectedly succeeded"),
            "constraints_depth20_tokens100000" => {
                assert!(parsed.is_ok(), "{stable_id} configured-constraint probe input failed: {parsed:?}");
                let depth_error = ProtobufJson::default().parse("protocol.HelloMessage", std::str::from_utf8(&behavior_input("@unknown-nested-object:21")).unwrap(), false).unwrap_err();
                assert!(depth_error.0.contains("recursion limit"));
                let token_error = parse_post_body(&behavior_input("@token-array:100500"), Some("application/json")).unwrap_err();
                assert!(token_error.0.contains("100000"), "{token_error:?}");
            }
            other => panic!("unknown C023 parser result {other}"),
        }
        assert_visible_int64_enum_field_json(row["symbol"].as_str().unwrap());
        assert_eq!(behavior["assertion"], format!("{}#{}:{parser_result}", std::path::Path::new(source_path).file_stem().unwrap().to_string_lossy(), row["symbol"].as_str().unwrap()));
        return RowOutcome { terminal: "mapped", result_key: row["result_key"].as_str().unwrap().to_owned() };
    }
    let route = behavior["route"].as_str().unwrap();
    let method = behavior["method"].as_str().unwrap();
    let expected: Vec<u16> = behavior["expected_status"].as_array().unwrap().iter().map(|value| value.as_u64().unwrap() as u16).collect();
    let mut controls = HttpControls::default();
    if kind == "control" && expected == [413] { controls.max_body_bytes = 4; }
    let (address, tx, task, path) = start(controls, false, 1, behavior_surface(behavior["surface"].as_str().unwrap())).await;
    let target = if method == "GET" {
        let query = std::str::from_utf8(&input).unwrap();
        if route.contains('?') { format!("{route}&{query}") } else { format!("{route}?{query}") }
    } else { route.to_owned() };
    let content_type = if method == "GET" { "application/x-www-form-urlencoded" } else { "application/json" };
    let (status, headers, response) = request(address, method, &target, content_type, if method == "GET" { b"" } else { &input }).await;
    assert!(expected.contains(&status), "{stable_id} exact {kind} behavior {method} route_len={} expected {expected:?}, received {status}", route.len());
    let assertion = behavior["assertion"].as_str().unwrap();
    assert!(assertion.contains(row["symbol"].as_str().unwrap()), "{stable_id} assertion is not source-specific");
    assert!(headers.to_ascii_lowercase().contains("content-type:"), "{stable_id} response omitted content type");
    assert!(!response.is_empty() || route == "/wallet/validateaddress", "{stable_id} response body semantics were not observable");
    if matches!(kind, "route" | "custom") && status == 200 {
        let body: serde_json::Value = serde_json::from_slice(&response).unwrap_or_else(|error| panic!("{stable_id} route returned non-JSON body: {error}"));
        assert!(body.is_object(), "{stable_id} route response must be a JSON object, got {body}");
    }
    stop(tx, task, path).await;
    RowOutcome { terminal: if kind == "deferred" { "deferred" } else { "mapped" }, result_key: row["result_key"].as_str().unwrap().to_owned() }
}

async fn assert_exact_java_row_proof(stable_id: &str, expected: &str, family: &str) {
    let reconciliation: serde_json::Value = serde_json::from_str(include_str!("../../../../docs/oracles/c023-ownership-reconciliation.v1.json")).unwrap();
    let row = reconciliation["rows"].as_array().unwrap().iter().find(|row| row["stable_id"] == stable_id).unwrap();
    let outcome = execute_row_behavior(stable_id, row).await;
    assert_eq!(outcome.terminal, row["terminal_state"].as_str().unwrap());
    assert_eq!(outcome.result_key, row["result_key"].as_str().unwrap());
    assert_eq!(row["fixture_selector"], stable_id);
    assert_eq!(row["expected_result"], expected);
    assert_eq!(row["rust_family_test"], family);
}

macro_rules! c023_row_proof {
    ($name:ident, $stable_id:literal, $expected:literal, $family:literal) => {
        #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
        async fn $name() { assert_exact_java_row_proof($stable_id, $expected, $family).await; }
    };
}

